import json, time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'
token = None
customer_cache = {}


def fetch_token():
    global token
    req = Request(BASE + '/token', method='POST')
    with urlopen(req, timeout=15) as resp:
        token = [REDACTED_SECRET]'token']


def request_json(path):
    global token
    refreshed = False
    while True:
        if token is None:
            fetch_token()
        req = Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
        try:
            with urlopen(req, timeout=15) as resp:
                return json.load(resp)
        except HTTPError as e:
            body = e.read().decode('utf-8', 'replace')
            if e.code == 401 and not refreshed:
                token = None
                refreshed = True
                continue
            if e.code == 429:
                delay = None
                retry_after = e.headers.get('Retry-After')
                if retry_after:
                    try:
                        delay = float(retry_after)
                    except ValueError:
                        pass
                if delay is None:
                    try:
                        payload = json.loads(body)
                        for k in ('retry_after', 'wait', 'wait_seconds', 'retryAfter'):
                            if k in payload:
                                delay = float(payload[k])
                                break
                    except Exception:
                        pass
                if delay is None:
                    raise RuntimeError(f'rate limited without wait duration: {body}')
                time.sleep(delay)
                continue
            if 500 <= e.code < 600:
                time.sleep(1)
                continue
            raise RuntimeError(f'GET {path} failed with {e.code}: {body}')
        except URLError:
            time.sleep(1)


def parse_utc(s):
    dt = datetime.fromisoformat(s.replace('Z', '+00:00'))
    return dt.astimezone(timezone.utc)

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end_exclusive = datetime(2025, 6, 1, tzinfo=timezone.utc)
seen = set()
duplicates_skipped = 0
orders = []
page = 1
page_count = None
while True:
    data = request_json(f'/orders?page={page}')
    if page_count is None:
        page_count = data['total_pages']
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates_skipped += 1
            continue
        seen.add(oid)
        orders.append(order)
    if not data.get('next'):
        break
    page += 1
    if page > page_count + 2:
        raise RuntimeError('pagination exceeded advertised total_pages')

by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
qualifying = 0
surprises = []
for order in orders:
    if order['status'] "'!= '"'shipped':
        continue
    placed = parse_utc(order['placed_at'])
    if not (start <= placed < end_exclusive):
        continue
    cid = order['customer_id']
    if cid not in customer_cache:
        customer_cache[cid] = request_json(f'/customers/{cid}')
    customer = customer_cache[cid]
    pct = customer['discount_pct']
    discounted = (Decimal(order['amount_cents']) * Decimal(100 - pct) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)
    qualifying += 1

total = sum(by_region.values())
result = {
    'total_cents': total,
    'order_count': qualifying,
    'duplicates_skipped': duplicates_skipped,
    'by_region': by_region,
}
print(json.dumps(result, sort_keys=True))
print(json.dumps({'pages': page_count, 'unique_listings': len(seen), 'customer_cache_size': len(customer_cache)}, sort_keys=True))
